// Block (composition) — a compact user summary card with optional stats and actions.
// Card and Avatar own their look; Stack owns grouping and alignment.
import type { ReactNode, Ref } from "react";
import { Avatar } from "../components/Avatar";
import { Card } from "../components/Card";
import { Stack } from "../layouts/Stack";
import "./ProfileCard.css";

export interface ProfileCardProps {
  name: string;
  role?: string;
  avatarSrc?: string;
  stats?: { label: string; value: string }[];
  actions?: ReactNode;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("") || "U";

export function ProfileCard({
  name,
  role,
  avatarSrc,
  stats,
  actions,
  className,
  ref,
}: ProfileCardProps) {
  return (
    <Card
      ref={ref}
      className={className ? `sd-profilecard ${className}` : "sd-profilecard"}
    >
      <Stack align="center" gap="small" className="sd-profilecard__content">
        <Avatar src={avatarSrc} alt={name} size="large">
          {initials(name)}
        </Avatar>
        {/* Name and role are ONE unit, at `x-small` because what follows them is a stat row and
            the actions slot — `token-contract.md` § Choosing a Sys rung, the pair's THIRD case.
            `2x-small` is for a pair that is all its container holds beside an avatar
            (`TestimonialGrid`, `SocialProof`, `MembersList`); here the pair is bounded by
            siblings, which is `TeamGrid`'s case and the same rung. */}
        <Stack align="center" gap="x-small" className="sd-profilecard__heading">
          <h2 className="sd-profilecard__name sd-type-title-medium">{name}</h2>
          {role && <p className="sd-profilecard__role sd-type-caption-medium">{role}</p>}
        </Stack>
        {stats && stats.length > 0 && (
          <Stack
            direction="row"
            align="center"
            justify="around"
            gap="small"
            wrap
            className="sd-profilecard__stats"
          >
            {stats.map((stat) => (
              <Stack key={stat.label} align="center" gap="2x-small" className="sd-profilecard__stat">
                <span className="sd-profilecard__value sd-type-body-medium">{stat.value}</span>
                {/* CONTRASTIVE: the stat's name reads one rung below the value it names (`__value`) above it. */}
                <span className="sd-profilecard__label sd-type-label-small">{stat.label}</span>
              </Stack>
            ))}
          </Stack>
        )}
        {/* spacing: attachment — the actions slot holds what acts on this profile (follow, message) */}
        {actions && (
          <Stack direction="row" justify="center" gap="small" wrap className="sd-profilecard__actions">
            {actions}
          </Stack>
        )}
      </Stack>
    </Card>
  );
}

/* ProfileCard.css — .sd-profilecard (Block)
   Arrangement only: fills the column it is given (the page sets it on the grid) and normalizes
   native text spacing. */
.sd-profilecard {
  width: 100%;
}

.sd-profilecard__name,
.sd-profilecard__role {
  margin: 0;
}

.sd-profilecard__role {
  color: var(--sd-color-text-muted);
}

.sd-profilecard__stats {
  width: 100%;
}
